	protected class SetBreakpointAction : AbstractSetBreakpointAction {
		public static readonly string GROUP = DebuggerResources.GROUP_BREAKPOINTS;

		private CommonSet kind;

		public SetBreakpointAction(CommonSet kind) : base(this)
    {
			this.kind = kind;
			setPopupMenuData(new MenuData(new string[] { NAME, kind.toString() }, ICON, GROUP));
			tool.addAction(this);
			setEnabled(true);
		}

		/* @Override */
		public void actionPerformed(ActionContext context) {
			if (!contextCanManipulateBreakpoints(context)) {
				return;
			}
			ProgramLocation location = getSingleLocationFromContext(context);
			long length = computeDefaultLength(context, kind);
			placeBreakpointDialog.prompt(tool, breakpointService, NAME, location, length, kind,
				"");
		}

		/* @Override */
		public bool isEnabledForContext(ActionContext context) {
			if (!contextCanManipulateBreakpoints(context)) {
				return false;
			}
			ProgramLocation loc = getSingleLocationFromContext(context);
			if (!(loc.getProgram() is TraceProgramView view)) {
				return true;
			}
			Set<TraceBreakpointKind> supported = getSupportedKindsFromTrace(view.getTrace());
			return supported.containsAll(kind.kinds());
		}
	}

	protected class EnableBreakpointAction : AbstractEnableBreakpointAction {
		public static readonly string GROUP = DebuggerResources.GROUP_BREAKPOINTS;

		public EnableBreakpointAction() : base(this)
    {
			setPopupMenuData(new MenuData(new string[] { NAME }, ICON, GROUP));
			tool.addAction(this);
			setEnabled(true);
		}

		/* @Override */
		public void actionPerformed(ActionContext context) {
			if (!contextCanManipulateBreakpoints(context)) {
				return;
			}
			List<ProgramLocation> locs = getLocationsFromContext(context);
			Set<LogicalBreakpoint> col = collectBreakpoints(locs);
			Trace trace = getTraceFromContext(context);
			string status = breakpointService.generateStatusEnable(col, trace);
			if (status != null) {
				tool.setStatusInfo(status, true);
			}
			breakpointService.enableAll(col, trace).exceptionally(ex => {
				breakpointError(NAME, "Could not enable breakpoint", ex);
				return null;
			});
		}

		/* @Override */
		public bool isEnabledForContext(ActionContext context) {
			if (!contextCanManipulateBreakpoints(context)) {
				return false;
			}
			List<ProgramLocation> locs = getLocationsFromContext(context);
			State state = computeState(locs);
			if (state == State.ENABLED || state == State.NONE) {
				return false;
			}
			return true;
		}
	}

	protected class DisableBreakpointAction : AbstractDisableBreakpointAction {
		public static readonly string GROUP = DebuggerResources.GROUP_BREAKPOINTS;

		public DisableBreakpointAction() : base(this)
    {
